import{_ as a,o as s,c as t,a3 as i}from"./chunks/framework.CchDE9cb.js";const k=JSON.parse('{"title":"TLS and networking","description":"How to put a domain and TLS certificate in front of CapacityLens, and the proxy, cookie and port requirements that come with it.","frontmatter":{"title":"TLS and networking","description":"How to put a domain and TLS certificate in front of CapacityLens, and the proxy, cookie and port requirements that come with it."},"headers":[],"relativePath":"self-hosting/tls-and-networking.md","filePath":"self-hosting/tls-and-networking.md","lastUpdated":null}'),n={name:"self-hosting/tls-and-networking.md"};function o(r,e,l,p,h,c){return s(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="tls-and-networking" tabindex="-1">TLS and networking <a class="header-anchor" href="#tls-and-networking" aria-label="Permalink to &quot;TLS and networking&quot;">​</a></h1><p>CapacityLens expects to sit behind a TLS-terminating reverse proxy on the same origin the browser uses. This page covers that proxy, the internal TLS hop Docker sets up for you, and the header and port details that make sign-in cookies work correctly.</p><h2 id="two-different-nginx-instances" tabindex="-1">Two different nginx instances <a class="header-anchor" href="#two-different-nginx-instances" aria-label="Permalink to &quot;Two different nginx instances&quot;">​</a></h2><p>It&#39;s easy to confuse these, so here&#39;s the plain-language version before anything else: the Docker Compose stack already contains its own nginx — the <code>web</code> service, configured by the repo&#39;s root <code>nginx.conf</code>. It serves the built app and reverse-proxies <code>/api/</code> to the API over an internal TLS hop it sets up for you. That nginx listens on <code>127.0.0.1:8080</code> and is not reachable from the internet.</p><p>The public reverse proxy is a <strong>second, separate thing</strong> — one you install and run on the host yourself, in front of that <code>127.0.0.1:8080</code>. It&#39;s the one that gets your domain name and a real certificate.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Browser (HTTPS, port 443)</span></span>
<span class="line"><span>    |</span></span>
<span class="line"><span>    v</span></span>
<span class="line"><span>Your public proxy (nginx or Caddy, run by you, on the host)</span></span>
<span class="line"><span>    |  connects over loopback</span></span>
<span class="line"><span>    v</span></span>
<span class="line"><span>127.0.0.1:8080 -&gt; the \`web\` service (Compose&#39;s own nginx)</span></span>
<span class="line"><span>    |  internal TLS hop</span></span>
<span class="line"><span>    v</span></span>
<span class="line"><span>the \`api\` service (Fastify)</span></span></code></pre></div><p>Do not edit the repository&#39;s <code>nginx.conf</code> to add public TLS — leave it alone. It already does its job (serving the app and proxying to the API); your public proxy is a separate config file, usually outside the repository entirely.</p><h2 id="the-public-edge" tabindex="-1">The public edge <a class="header-anchor" href="#the-public-edge" aria-label="Permalink to &quot;The public edge&quot;">​</a></h2><p>Put a reverse proxy or load balancer in front of CapacityLens and terminate public HTTPS there — nginx, Caddy, a platform load balancer, whatever you already run. Never expose the API container directly.</p><ul><li>The Docker Compose <code>web</code> service binds port 8080 to <code>127.0.0.1</code> by default, so only a proxy on the same host can reach it. Set <code>WEB_BIND_IP</code> only if a private platform load balancer needs to reach the container host over a network you trust.</li><li>The public edge must overwrite <code>X-Forwarded-Proto</code> with the browser-visible scheme — not append to it. CapacityLens trusts this single hop for CSRF&#39;s same-origin check and for per-client rate limiting.</li><li>If that proxy already emits its own HSTS header, leave <code>CAPACITYLENS_HTTPS</code> unset. Otherwise set <code>CAPACITYLENS_HTTPS=1</code> once the public response is genuinely HTTPS, and CapacityLens adds a two-year HSTS header itself.</li><li><code>SMALLSASS_ACCOUNT_PUBLIC_URL</code> must exactly match the browser origin the proxy serves, including the scheme.</li></ul><h3 id="nginx-example" tabindex="-1">nginx example <a class="header-anchor" href="#nginx-example" aria-label="Permalink to &quot;nginx example&quot;">​</a></h3><p>A minimal, complete <code>server {}</code> block. It terminates HTTPS and reverse-proxies everything to the <code>web</code> service on <code>127.0.0.1:8080</code>:</p><div class="language-nginx vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">nginx</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">server</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    listen </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">443</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ssl;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    listen </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[::]:443 ssl;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    server_name </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">capacity.example.com;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    ssl_certificate </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    /etc/letsencrypt/live/capacity.example.com/fullchain.pem;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    ssl_certificate_key </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/etc/letsencrypt/live/capacity.example.com/privkey.pem;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    location</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> / </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        proxy_pass </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">http://127.0.0.1:8080;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        proxy_set_header </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Host $host;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        proxy_set_header </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">X-Real-IP $remote_addr;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        proxy_set_header </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">X-Forwarded-For $remote_addr;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        proxy_set_header </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">X-Forwarded-Proto $scheme;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">server</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    listen </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">80</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    listen </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[::]:80;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    server_name </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">capacity.example.com;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    return</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 301</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> https://$host$request_uri;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Get the certificate with <a href="https://certbot.eff.org" target="_blank" rel="noreferrer">certbot</a>: it can write the <code>ssl_certificate</code> lines above for you and handles renewal. Follow certbot&#39;s nginx instructions for your OS rather than hand-editing paths.</p><h3 id="caddy-example" tabindex="-1">Caddy example <a class="header-anchor" href="#caddy-example" aria-label="Permalink to &quot;Caddy example&quot;">​</a></h3><p>Caddy is the easier path if you&#39;re new to this: it requests and renews a Let&#39;s Encrypt certificate automatically, with no separate certbot step. A complete <code>Caddyfile</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>capacity.example.com {</span></span>
<span class="line"><span>    reverse_proxy 127.0.0.1:8080</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>That&#39;s the whole config — Caddy fills in HTTPS, the redirect from port 80, and the forwarded headers CapacityLens needs.</p><p>Loopback API listeners (<code>127.0.0.1</code>, <code>localhost</code> or <code>::1</code>) — which is every packaged Compose and the recommended bare-metal setup — automatically trust their same-host proxy&#39;s forwarded headers. <code>CAPACITYLENS_TRUST_PROXY_HEADERS=1</code> opts a non-loopback listener into the same trust, and is safe only when clients can&#39;t reach the API directly. Docker Compose sets it because the API only listens on the private container network, reachable solely by the packaged nginx.</p><h2 id="cookies-and-host-requirements" tabindex="-1">Cookies and host requirements <a class="header-anchor" href="#cookies-and-host-requirements" aria-label="Permalink to &quot;Cookies and host requirements&quot;">​</a></h2><p>CapacityLens signs the browser in with a <code>__Host-</code>-prefixed cookie once <code>SMALLSASS_ACCOUNT_PUBLIC_URL</code> is HTTPS. That cookie prefix requires the browser to see a single, secure, root-path origin — which is exactly what the same-origin proxy topology above provides, and why the API is never exposed on its own origin or port.</p><p>If the browser and API are intentionally on different origins — a separate origin for the SPA, for example — set <code>CAPACITYLENS_CORS_ORIGIN</code> to the comma-separated browser origins. Host case, default ports and a trailing slash are normalised automatically; credentials, paths, queries, fragments and <code>*</code> are all rejected at startup, because CapacityLens recognises a signed-in browser with cookies, not tokens. With the packaged same-origin nginx proxy, leave <code>CAPACITYLENS_CORS_ORIGIN</code> unset — the browser never makes a cross-origin API call.</p><h2 id="the-internal-hop-docker-compose" tabindex="-1">The internal hop (Docker Compose) <a class="header-anchor" href="#the-internal-hop-docker-compose" aria-label="Permalink to &quot;The internal hop (Docker Compose)&quot;">​</a></h2><p>Inside the packaged Compose stack, nginx doesn&#39;t talk to the API in plaintext. Before either long-running service starts, a one-shot <code>internal-tls</code> service creates a private, per-install certificate authority and an API leaf certificate on a dedicated volume. nginx verifies the <code>api</code> service name and the certificate authority over TLS 1.2/1.3 for every request it proxies; the API listener has no plaintext fallback. The certificate authority&#39;s own key stays root-only, the API container can read only its own leaf key, and nginx can read only public certificates.</p><p>The initializer reuses a valid certificate set on restart rather than recreating it. Renew the leaf within 30 days of expiry:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./scripts/renew-internal-tls.sh</span></span></code></pre></div><p>This stops both TLS consumers, force-recreates them and verifies their live certificate generation through nginx before reporting success. Deep <code>/api/health</code> reports the cached leaf expiry and live certificate fingerprint, and its <code>internalTls.status</code> field changes from <code>ok</code> to <code>expiring</code> during that same 30-day window — alert on that field. See <a href="/capacitylens/self-hosting/monitoring">Monitoring and health checks</a>.</p><h2 id="bare-metal-nginx" tabindex="-1">Bare-metal nginx <a class="header-anchor" href="#bare-metal-nginx" aria-label="Permalink to &quot;Bare-metal nginx&quot;">​</a></h2><p>Without Docker, run the API bound to loopback and terminate public HTTPS at nginx:</p><ul><li>Set <code>CAPACITYLENS_HOST=127.0.0.1</code>.</li><li>Use <code>proxy_pass http://127.0.0.1:8787;</code> — 8787 is the API&#39;s default port.</li><li>Route <code>/api/</code> without stripping the prefix; the server mounts every route under <code>/api/</code>.</li><li>Overwrite both <code>X-Forwarded-For</code> and <code>X-Forwarded-Proto</code> the way the packaged <code>nginx.conf</code> does, and reuse its security headers.</li></ul><p>For defense in depth on the internal hop, create your own internal CA-signed service certificate, set both <code>CAPACITYLENS_INTERNAL_TLS_CERT</code> and <code>CAPACITYLENS_INTERNAL_TLS_KEY</code>, then switch nginx to <code>proxy_pass https://127.0.0.1:8787;</code> with <code>proxy_ssl_verify on</code>, your trusted CA and a matching <code>proxy_ssl_name</code>. Once you configure either variable, both are required — a partial, empty or unreadable pair refuses startup rather than silently falling back to HTTP.</p><h2 id="ports-at-a-glance" tabindex="-1">Ports at a glance <a class="header-anchor" href="#ports-at-a-glance" aria-label="Permalink to &quot;Ports at a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Port</th><th>What&#39;s listening</th><th>Reachable from</th></tr></thead><tbody><tr><td>8080</td><td>nginx (web app + <code>/api/</code> proxy)</td><td>Loopback by default; your reverse proxy</td></tr><tr><td>8787</td><td>The API (Fastify)</td><td>Only nginx, over the internal TLS hop in Compose, or loopback on bare metal</td></tr></tbody></table><h2 id="what-s-next" tabindex="-1">What&#39;s next <a class="header-anchor" href="#what-s-next" aria-label="Permalink to &quot;What&#39;s next&quot;">​</a></h2><ul><li><a href="/capacitylens/self-hosting/install-with-docker">Install with Docker</a> if you&#39;re setting this up for the first time.</li><li><a href="/capacitylens/self-hosting/monitoring">Monitoring and health checks</a> to watch certificate expiry and proxy health once it&#39;s running.</li></ul>`,35)])])}const g=a(n,[["render",o]]);export{k as __pageData,g as default};
